    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // transfer requires a non-empty _tos; restrict inputs so the call can potentially succeed
        require(_tos.length > 0);

        bool returnedTrue = false;
        bool reverted = false;

        // Call transfer and detect whether it reverted
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            returnedTrue = r;
            reverted = false;
        } catch {
            reverted = true;
            returnedTrue = false;
        }

