    // Single public test function: drives c.transfer and asserts a general rule
    function run(address from, address caddress, address[] memory _tos, uint v) public payable {
        // Require a non-empty _tos so transfer's initial require can pass
        require(_tos.length > 0);

        bool ok = false;
        bool didRevert = false;

        // Call transfer and observe whether it reverts and its return value
        try c.transfer(from, caddress, _tos, v) returns (bool r) {
            ok = r;
            didRevert = false;
        } catch {
            ok = false;
            didRevert = true;
        }

        // General rule: if transfer returned true then it did not revert (i.e., all internal calls succeeded)
        assert(!ok || !didRevert);
    }

